const current = $input.first().json; const s=current.state;
let verdict='HOLD'; let missing=[];
if (s.qualified === false) { verdict='NO_BID'; missing=['OUTSIDE_TARGET']; }
else if (s.eligibility === 'ineligible' || !s.deadline_open) { verdict='NO_BID'; missing=['MANDATORY_QUALIFICATION_OR_DEADLINE']; }
else {
  const required={assigned:'NO_CASE',official:'UNVERIFIED_ORIGINAL',detail10:'UNVERIFIED_DETAIL10',docs:'MISSING_DOCUMENTS',history_verified:'HISTORY_NOT_FULLY_VERIFIED',competitor:'COMPETITOR_ANALYSIS_MISSING',price:'PRICE_UNVERIFIED',package:'PACKAGE_INCOMPLETE',audit:'AUDIT_NOT_CLEARED',lease_valid:'WORKER_LEASE_INVALID'};
  for (const [key,reason] of Object.entries(required)) { if (!s[key]) missing.push(reason); }
  if (s.coverage_done!==s.coverage_total) missing.push('HISTORY_'+s.coverage_done+'/'+s.coverage_total);
  if (s.eligibility!=='eligible') missing.push('ELIGIBILITY_UNKNOWN');
  if (s.quotes<s.quote_required) missing.push('VALID_QUOTES_INSUFFICIENT');
  if (s.critical_audit) missing.push('CRITICAL_AUDIT_FINDING');
  if (!missing.length) {
    if (!s.human) { verdict='REVIEW'; missing=['HUMAN_APPROVAL_REQUIRED']; }
    else verdict='READY_FOR_MANUAL_PARTICIPATION';
  }
}
if (verdict!==current.expected) throw new Error('Scenario policy error: expected '+current.expected+' got '+verdict+' ('+missing.join(',')+')');
return [{json:{...current,verdict,missing,passed:true,simulation_only:true,bid_submitted:false}}];
